from datetime import datetime, timedelta

def parse_dt(s):
    if s is None:
        return None
    s2=s
    if isinstance(s2,str) and s2.endswith('Z'):
        s2=s2[:-1]+'+00:00'
    try:
        return datetime.fromisoformat(s2)
    except Exception:
        try:
            return datetime.strptime(s2.split('.')[0], '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return None

